<?php
declare(strict_types=1);
namespace App\Repositories;
use App\Core\Database;
final class StudentRepository{
public function __construct(private readonly Database $db){}
public function db():Database{return$this->db;}
public function paginate(int $institute,string $search='',?int $class=null,int $limit=0,bool $onlyDue=false):array{$sql='SELECT s.*,c.name class_name,COALESCE((SELECT SUM(fi.remaining_amount) FROM fee_invoices fi WHERE fi.student_id=s.id AND fi.voided_at IS NULL),0) fee_remaining FROM students s JOIN classes c ON c.id=s.class_id WHERE s.institute_id=:i AND (s.student_name LIKE :q OR s.registration_no LIKE :q2 OR c.name LIKE :q3)'.($class?' AND s.class_id=:class':'').($onlyDue?' HAVING fee_remaining>0':'').' ORDER BY s.student_name ASC,s.registration_no ASC,s.id ASC'.($limit>0?' LIMIT '.(int)$limit:'');$p=['i'=>$institute,'q'=>'%'.$search.'%','q2'=>'%'.$search.'%','q3'=>'%'.$search.'%'];if($class)$p['class']=$class;return $this->db->query($sql,$p)->fetchAll();}
public function basicList(int$institute,string$search='',?int$class=null,int$limit=0):array{$sql='SELECT s.id,s.registration_no,s.student_name,s.father_name,s.mobile,c.name class_name,COALESCE(SUM(fi.remaining_amount),0) fee_remaining FROM students s JOIN classes c ON c.id=s.class_id LEFT JOIN fee_invoices fi ON fi.student_id=s.id WHERE s.institute_id=:i AND (s.student_name LIKE :q OR s.registration_no LIKE :q2)'.($class?' AND s.class_id=:c':'').' GROUP BY s.id,c.name ORDER BY s.student_name ASC,s.registration_no ASC,s.id ASC'.($limit>0?' LIMIT '.(int)$limit:'');$p=['i'=>$institute,'q'=>'%'.$search.'%','q2'=>'%'.$search.'%'];if($class)$p['c']=$class;return$this->db->query($sql,$p)->fetchAll();}
public function find(int $id,int $institute):?array{$r=$this->db->query('SELECT s.*,c.name class_name,c.monthly_tuition FROM students s JOIN classes c ON c.id=s.class_id WHERE s.id=:id AND s.institute_id=:i',['id'=>$id,'i'=>$institute])->fetch();return $r?:null;}
public function documents(int$id,int$institute):array{return$this->db->query('SELECT d.* FROM student_documents d JOIN students s ON s.id=d.student_id WHERE d.student_id=:id AND s.institute_id=:i ORDER BY d.created_at DESC,d.id DESC',['id'=>$id,'i'=>$institute])->fetchAll();}
public function addDocument(array$d):int{$this->db->query('INSERT INTO student_documents(student_id,document_type,original_name,file_path,mime_type,file_size,uploaded_by,created_at) VALUES(:student_id,:document_type,:original_name,:file_path,:mime_type,:file_size,:uploaded_by,:created_at)',$d);return(int)$this->db->connection()->lastInsertId();}
public function byRegistration(string $reg,int $institute):?array{$r=$this->db->query('SELECT s.*,c.name class_name,c.monthly_tuition FROM students s JOIN classes c ON c.id=s.class_id WHERE s.registration_no=:r AND s.institute_id=:i',['r'=>$reg,'i'=>$institute])->fetch();return $r?:null;}
public function classIsValid(int $class,int $institute):bool{return(bool)$this->db->query('SELECT 1 FROM classes WHERE id=:id AND institute_id=:i',['id'=>$class,'i'=>$institute])->fetchColumn();}
public function create(array $d):int{\App\Platform\Features::assertRoom($this->db,'students');$cols=array_keys($d);$sql='INSERT INTO students('.implode(',',$cols).') VALUES (:'.implode(',:',$cols).')';$this->db->query($sql,$d);return(int)$this->db->connection()->lastInsertId();}
public function createMany(array$rows):int{\App\Platform\Features::assertRoom($this->db,'students',count($rows));$pdo=$this->db->connection();$pdo->beginTransaction();try{foreach($rows as$row)$this->create($row);$pdo->commit();return count($rows);}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
public function classesForImport(int$i):array{return$this->db->query('SELECT id,name FROM classes WHERE institute_id=:i ORDER BY name',['i'=>$i])->fetchAll();}
public function registrations(int$i):array{return$this->db->query('SELECT registration_no FROM students WHERE institute_id=:i',['i'=>$i])->fetchAll(\PDO::FETCH_COLUMN);}
public function update(int $id,int $institute,array $d):bool{$sets=[];foreach(array_keys($d) as $c)$sets[]="$c=:$c";$d['id']=$id;$d['institute']=$institute;$s=$this->db->query('UPDATE students SET '.implode(',',$sets).' WHERE id=:id AND institute_id=:institute',$d);return$s->rowCount()>0;}
public function setStatus(int $id,int $institute,string $status):bool{return$this->db->query('UPDATE students SET status=:s,updated_at=:u WHERE id=:id AND institute_id=:i',['s'=>$status,'u'=>date('Y-m-d H:i:s'),'id'=>$id,'i'=>$institute])->rowCount()>0;}
public function setStatuses(array$ids,int$institute,string$status):int{$ids=array_values(array_unique(array_filter(array_map('intval',$ids))));if(!$ids)return 0;$marks=implode(',',array_fill(0,count($ids),'?'));$statement=$this->db->connection()->prepare("UPDATE students SET status=?,updated_at=? WHERE institute_id=? AND id IN ({$marks})");$statement->execute(array_merge([$status,date('Y-m-d H:i:s'),$institute],$ids));return$statement->rowCount();}
public function updateFamilies(int$institute,array$families):int{$updated=0;foreach($families as$id=>$family){$updated+=$this->db->query('UPDATE students SET family=:family,updated_at=:updated WHERE id=:id AND institute_id=:institute',['family'=>trim((string)$family)?:null,'updated'=>date('Y-m-d H:i:s'),'id'=>(int)$id,'institute'=>$institute])->rowCount();}return$updated;}
/**
 * Deletes a student only when nothing references them. Most child tables cascade, so deleting a
 * student with history would silently erase their attendance, marks, tests and documents — set
 * them Inactive instead (their history stays). Returns deleted | in_use | missing.
 */
public function deleteStudent(int $id,int $institute):string{if(!$this->find($id,$institute))return'missing';if($this->historyFor($id))return'in_use';$this->db->query('DELETE FROM person_status_history WHERE person_type=\'student\' AND person_id=:id',['id'=>$id]);$this->db->query('DELETE FROM students WHERE id=:id AND institute_id=:i',['id'=>$id,'i'=>$institute]);return'deleted';}
/** @return list<string> human names of the record types that exist for this student */
public function historyFor(int $id):array{$found=[];foreach(['fee_invoices'=>'fee invoices','fee_payments'=>'fee payments','student_attendance'=>'attendance','exam_marks'=>'exam marks','class_test_marks'=>'class test marks','online_test_attempts'=>'online tests','student_documents'=>'documents','behaviour_observations'=>'behaviour records','behaviour_ratings'=>'behaviour ratings','certificates'=>'certificates','student_promotions'=>'promotions','student_accounts'=>'a portal login','live_class_participants'=>'live classes','homework'=>'homework','class_notes'=>'notes'] as$table=>$label){try{if($this->db->query("SELECT 1 FROM {$table} WHERE student_id=:id LIMIT 1",['id'=>$id])->fetchColumn())$found[]=$label;}catch(\Throwable){}}return$found;}
public function deleteStudents(array $ids,int $institute):array{$out=['deleted'=>0,'blocked'=>0,'missing'=>0];foreach(array_unique(array_map('intval',$ids))as$id){$s=$this->deleteStudent($id,$institute);if($s==='deleted')$out['deleted']++;elseif($s==='in_use')$out['blocked']++;else$out['missing']++;}return$out;}
}
